  if(form.id==='user-form'){await withForm(form,'user-status',async()=>{const next=structuredClone(state),name=form.elements.name.value.trim(),email=form.elements.email.value.trim(),expires=form.elements.expires.value;if(!name||!expires)throw Error('Completá el nombre y el vencimiento.');if(email&&next.demoMembers.some(m=>m.id!==form.dataset.id&&m.email?.toLowerCase()===email.toLowerCase()))throw Error('Ya existe un usuario con ese correo.');const existing=next.demoMembers.find(m=>m.id===form.dataset.id);if(existing)Object.assign(existing,{name,email,expires});else next.demoMembers.push({id:crypto.randomUUID(),name,email,expires,active:true});if(!save(next))throw Error('No se pudo guardar el usuario.');dirty=false;closeDialog();render();notify('Usuario guardado.');});return;}
  if(form.id==='bulk-library-form'){await withForm(form,'bulk-status',async()=>{const files=[...form.elements.files.files],normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\.[^.]+$/,'').replace(/[^a-z0-9]/g,'');const jobs=files.map(file=>{const match=state.contents.find(c=>normalize(c.importFile||c.title)===normalize(file.name));if(!match)throw Error('No hay una ficha para '+file.name+'. Cargalo desde Nuevo contenido.');if(file.size>50000000)throw Error(file.name+' supera 50 MB.');if(!file.type.startsWith(match.kind==='video'?'video/':'audio/'))throw Error('El formato no coincide para '+file.name);return {file,id:match.id};});if(!jobs.length)throw Error('Seleccioná los archivos.');let completed=0;for(const job of jobs){const result=await SatvicoSync.uploadLibrary(job.file,p=>status('bulk-status',`${completed+1}/${jobs.length} · ${job.file.name} · ${p}%`));const next=structuredClone(state),c=next.contents.find(c=>c.id===job.id);c.privatePath=result.privatePath;c.media='';if(form.elements.publish.checked)c.published=true;next.settings.catalogue=next.contents;await publishSettings(next);completed++;status('bulk-status',`${completed}/${jobs.length} archivos guardados en línea.`);}render();notify(completed+' archivos cargados y asociados.');});return;}
