 async function localFile(key){const database=await db();return new Promise((resolve,reject)=>{const req=database.transaction('media').objectStore('media').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('No se pudo leer el archivo guardado.'));});}
 async function publishSettings(next){const published=await SatvicoSync.publish(next.settings,localFile,p=>{const el=$('settings-status');if(el)el.textContent='Subiendo archivo… '+p+'%';});next.settings=published.settings;if(Array.isArray(published.settings.catalogue))next.contents=published.settings.catalogue;next.syncRevision=published.revision;state=next;save(next);}
 async function refreshShared(){if(route==='admin'||dirty||modal.open||document.hidden)return;try{const remote=await SatvicoSync.read();if(remote.revision!==state.syncRevision){state.settings=remote.settings;state.contents=remote.settings.catalogue||structuredClone(initial.contents);state.syncRevision=remote.revision;save();render();}}catch{}}
 async function start(){try{const response=await fetch(new URL('defaults.json',BASE),{cache:'no-store'});if(!response.ok)throw Error();initial=await response.json();try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');state=saved?.version===1&&Array.isArray(saved.contents)&&saved.settings&&saved.member&&Array.isArray(saved.demoMembers)?saved:structuredClone(initial);}catch{state=structuredClone(initial);}if(state.assetRevision!==2){const replacements={'assets/yoga-hero.webp':'assets/instructora-cuencos.webp','assets/oceano.webp':'assets/cuencos-estudio.webp','assets/reflexion.webp':'assets/rincon-estudio.webp'};if(replacements[state.settings.heroImage])state.settings.heroImage=replacements[state.settings.heroImage];for(const c of state.contents){if(replacements[c.image])c.image=c.category==='yoga'?'assets/yoga-aereo.webp':replacements[c.image];}state.assetRevision=2;save();}if(state.visualRevision!==4){if(state.settings.logo==='assets/logo.webp')state.settings.logo='assets/logo-transparente.png';state.visualRevision=4;save();}if(state.managementRevision!==14){state.demoMembers=state.demoMembers.filter(m=>!/^Alumno de muestra/.test(m.name));if(state.settings.libraryTitle==='Elegí tu momento de bienestar')state.settings.libraryTitle='Nuestros espacios';state.managementRevision=14;save();}if(state.accountsRevision!==15){state.member.active=false;sessionStorage.removeItem('satvico-member-demo');state.accountsRevision=15;save();}if(state.heroVideoRevision!==16){if(state.settings.heroImage==='assets/instructora-cuencos.webp'){state.settings.heroImage='assets/portada-yoga.mp4';state.settings.heroMediaType='video';state.settings.heroAspectRatio=1;}state.heroVideoRevision=16;save();}state.settings.showAmbient=state.settings.showAmbient!==false;try{if(state.syncRevision===undefined&&!localStorage.getItem(KEY+'-before-sync'))localStorage.setItem(KEY+'-before-sync',JSON.stringify(state.settings));}catch{}try{const remote=await SatvicoSync.read();state.settings=remote.settings;state.contents=remote.settings.catalogue||structuredClone(initial.contents);state.syncRevision=remote.revision;save();}catch{notify('No se pudo comprobar la portada publicada. Se muestra la última versión disponible.');}await hydrate();readRoute();setInterval(refreshShared,30000);window.addEventListener('focus',refreshShared);}catch{main.innerHTML='<div class="wrap section"><h1>No pudimos abrir la demo.</h1><p>Recargá la página para volver a intentar.</p></div>';}}
